import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createOrder} from '../src/order.mjs';

test('hidden check', async () => {
  const order = createOrder({items: [{price: 1000, quantity: 2}, {price: 500, quantity: 3}]});
  assert.equal(order.itemCount, 5);
  assert.equal(order.subtotal, 3500);
  assert.equal(order.total, 6500);
});
